import "server-only";
// NOTE: this file is listed in tsconfig.json's `exclude`, so neither
// `next build` nor `tsc --noEmit` type-checks it. The `cloudflare:workers`
// types come from .cloudflare/types, which is generated by the Workers build
// and gitignored - so on a clean checkout (Netlify, CI) the module cannot
// resolve and the Next type check would fail. Vite resolves this file by path
// through the alias in vite.config.ts, independently of tsconfig, so the
// Workers build is unaffected. Keep the logic here trivial.
import { env } from "cloudflare:workers";

/**
 * Cloudflare Workers implementation of {@link getEnv}, substituted for
 * `runtime-env.ts` by the resolve.alias in vite.config.ts.
 *
 * Worker secrets and vars are declared in cloudflare.config.ts and surface on
 * the `env` object from `cloudflare:workers`; `process.env` stays empty.
 */
export function getEnv(key: string): string | undefined {
  const value = (env as unknown as Record<string, unknown>)[key];
  return typeof value === "string" ? value : undefined;
}
